-- Schema für neue Tenant-DBs (z.B. gradify_studiengang_xyz)
CREATE TABLE IF NOT EXISTS mandanten (id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, kuerzel VARCHAR(10) NOT NULL UNIQUE, aktiv BOOLEAN NOT NULL DEFAULT true, erstellt_am TIMESTAMP, aktualisiert_am TIMESTAMP);
CREATE TABLE IF NOT EXISTS studiengaenge (id BIGSERIAL PRIMARY KEY, mandant_id BIGINT NOT NULL REFERENCES mandanten(id), name VARCHAR(150) NOT NULL, kuerzel VARCHAR(20) NOT NULL UNIQUE, abschlussart VARCHAR(20) NOT NULL, regelstudienzeit INT NOT NULL, gesamt_ects INT NOT NULL, studienvariante VARCHAR(20) NOT NULL DEFAULT 'ALLGEMEIN', aktiv BOOLEAN NOT NULL DEFAULT true, aktuelle_po_id BIGINT, erstellt_am TIMESTAMP, aktualisiert_am TIMESTAMP);
CREATE TABLE IF NOT EXISTS pruefungsordnungen (id BIGSERIAL PRIMARY KEY, studiengang_id BIGINT NOT NULL REFERENCES studiengaenge(id), version VARCHAR(20) NOT NULL, gueltig_ab DATE NOT NULL, gueltig_bis DATE, berechnungsart VARCHAR(30) NOT NULL, dokument_referenz VARCHAR(255), erstellt_am TIMESTAMP);
DO $$ BEGIN ALTER TABLE studiengaenge ADD CONSTRAINT fk_studiengang_po FOREIGN KEY (aktuelle_po_id) REFERENCES pruefungsordnungen(id); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS module (id BIGSERIAL PRIMARY KEY, po_id BIGINT NOT NULL REFERENCES pruefungsordnungen(id), modul_nr VARCHAR(10) NOT NULL, name VARCHAR(200) NOT NULL, name_en VARCHAR(200), ects INT NOT NULL, semester VARCHAR(10) NOT NULL, dauer_semester INT NOT NULL DEFAULT 1, pruefungsform VARCHAR(20) NOT NULL, pruefungsdauer VARCHAR(200), sprache VARCHAR(20) NOT NULL DEFAULT 'DEUTSCH', modultyp VARCHAR(20) NOT NULL, bewertungsart VARCHAR(30) NOT NULL, gewichtung DECIMAL(3,1) NOT NULL, in_gesamtnote BOOLEAN NOT NULL DEFAULT true, vorleistung VARCHAR(500), wahlpflicht_gruppe VARCHAR(20));
CREATE TABLE IF NOT EXISTS einschreibungen (id BIGSERIAL PRIMARY KEY, student_id BIGINT NOT NULL, studiengang_id BIGINT NOT NULL REFERENCES studiengaenge(id), po_id BIGINT NOT NULL REFERENCES pruefungsordnungen(id), studienvariante VARCHAR(20) NOT NULL DEFAULT 'ALLGEMEIN', immatrikuliert_am DATE NOT NULL, exmatrikuliert_am DATE, aktuelles_semester INT NOT NULL DEFAULT 1, status VARCHAR(20) NOT NULL DEFAULT 'AKTIV', erstellt_am TIMESTAMP);
CREATE TABLE IF NOT EXISTS po_regelwerke (id BIGSERIAL PRIMARY KEY, po_id BIGINT NOT NULL UNIQUE REFERENCES pruefungsordnungen(id), regel_name VARCHAR(100) NOT NULL, beschreibung TEXT, formel VARCHAR(500) NOT NULL, parameter_json TEXT);
CREATE TABLE IF NOT EXISTS modul_zuweisungen (id BIGSERIAL PRIMARY KEY, dozent_id BIGINT NOT NULL, modul_id BIGINT NOT NULL, bemerkung VARCHAR(255));
CREATE TABLE IF NOT EXISTS modul_zuweisung_historie (id BIGSERIAL PRIMARY KEY, dozent_id BIGINT NOT NULL, modul_id BIGINT NOT NULL, geaendert_von BIGINT NOT NULL, aenderungs_typ VARCHAR(50) NOT NULL, kommentar VARCHAR(500), geaendert_am TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS wahlpflicht_wahlen (id BIGSERIAL PRIMARY KEY, einschreibung_id BIGINT NOT NULL REFERENCES einschreibungen(id), wahlpflicht_gruppe VARCHAR(20) NOT NULL, modul_id BIGINT NOT NULL REFERENCES module(id), erstellt_am TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(einschreibung_id, wahlpflicht_gruppe));
-- Performance Indexes
CREATE INDEX IF NOT EXISTS idx_studiengaenge_mandant_id ON studiengaenge(mandant_id);
CREATE INDEX IF NOT EXISTS idx_einschreibungen_student_id ON einschreibungen(student_id);
CREATE INDEX IF NOT EXISTS idx_einschreibungen_studiengang_id ON einschreibungen(studiengang_id);
CREATE INDEX IF NOT EXISTS idx_einschreibungen_po_id ON einschreibungen(po_id);
CREATE INDEX IF NOT EXISTS idx_module_po_id ON module(po_id);
CREATE INDEX IF NOT EXISTS idx_modul_zuweisungen_dozent_id ON modul_zuweisungen(dozent_id);
CREATE INDEX IF NOT EXISTS idx_modul_zuweisungen_modul_id ON modul_zuweisungen(modul_id);
CREATE INDEX IF NOT EXISTS idx_modul_zuweisung_historie_geaendert_am ON modul_zuweisung_historie(geaendert_am);